def fib4(n: int):
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the base cases
    a, b, c, d = 0, 0, 2, 0

    # Compute the n-th element iteratively
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d

    return d
```

```python
def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    shifts = 0

    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            shifts += 1
            if shifts > 1:
                return False
            if i > 0 and arr[i - 1] > arr[i + 1]:
                return False
    # Check the last and first element condition
    if arr[n - 1] > arr[0]:
        shifts += 1
        if shifts > 1:
            return False

    return True
```
